// Bouton Play/Pause : rond, aligné à gauche de la barre (premier enfant flex), même teinte de
// verre que le fond de la barre mais légèrement plus opaque pour se détacher comme un vrai bouton.
.playButton {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.06);
  color: #e4e4e7;
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease;

  // Le trait vertical de Pause (`fill-current`, 14px) atterrit visuellement décentré vers la
  // gauche par rapport au triangle de Play : recentrage optique, pas géométrique.
  svg {
    margin-left: 1px;
  }

  &:hover:not(:disabled) {
    background: rgba(255, 255, 255, 0.12);
    border-color: rgba(0, 240, 255, 0.4);
    color: #00f0ff;
  }

  &:disabled {
    opacity: 0.35;
    cursor: default;
  }
}

// Curseur de prévisualisation : occupe l'espace restant à droite du bouton Play. Zone de
// interaction plus haute que le rail visuel (comme un <input type="range">) pour rester facile à
// saisir, le rail et la poignée n'étant que des enfants centrés dedans.
.track {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  height: 100%;
  display: flex;
  align-items: center;
  cursor: pointer;
  touch-action: none;

  &[aria-disabled='true'] {
    cursor: default;
  }
}

.trackRail {
  position: relative;
  width: 100%;
  height: 3px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.12);
  overflow: hidden;
}

.trackFill {
  position: absolute;
  inset: 0 auto 0 0;
  height: 100%;
  border-radius: inherit;
  background: #00f0ff;
  // La poignée porte son propre halo lumineux ; le rail reste net pour ne pas le dupliquer.
}

// Poignée ronde du curseur, distincte du rail : un léger espace (border transparente élargissant
// la zone cliquable sans toucher le rail) la sépare visuellement de la barre de remplissage,
// plutôt que de la faire chevaucher le rail comme un thumb natif classique.
.trackHandle {
  position: absolute;
  top: 50%;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #00f0ff;
  box-shadow: 0 0 0 4px rgba(10, 15, 26, 0.6), 0 0 8px 1px rgba(0, 240, 255, 0.6);
  transform: translate(-50%, -50%);
  pointer-events: none;
  transition: box-shadow 0.15s ease;
}

.track:hover .trackHandle {
  box-shadow: 0 0 0 4px rgba(10, 15, 26, 0.6), 0 0 10px 2px rgba(0, 240, 255, 0.85);
}

