1	import React, { useCallback, useRef } from 'react';
2	import { motion, AnimatePresence } from 'framer-motion';
3	import { Play, Pause } from 'lucide-react';
4	import { type GCodeFileInfo } from '@/hooks/use-gcode-preview';
5	import styles from './GCodePreviewBar.module.scss';
6	
7	interface GCodePreviewBarProps {
8	  /** Espace Prévisualisation affiché — pilote l'apparition/disparition de la barre elle-même. */
9	  active: boolean;
10	  fileInfo: GCodeFileInfo | null;
11	  t: number;
12	  lastIndex: number;
13	  isPlaying: boolean;
14	  togglePlay: () => void;
15	  seek: (value: number) => void;
16	  speed: number;
17	  setSpeed: (speed: number) => void;
18	  showTravel: boolean;
19	  setShowTravel: (show: boolean) => void;
20	  openFilePicker: () => void;
21	}
22	
23	// `active` (isPreviewActive) devient vrai dans `onCovered` (cf. Sidebar.tsx), à l'instant précis
24	// où le rideau plein écran (SpaceTransitionOverlay) vient de finir de se peindre — PAS quand il a
25	// fini de se lever. À ce même instant démarrent aussi, tous masqués par le rideau : la mitose
26	// pilule → panneaux de CategoriesSidebar (PREVIEW_MORPH_MS = 1370ms) et le déplacement de la barre
27	// d'aide TopRightMenu (RESHAPE_DURATION = 1100ms) — les deux plus longues animations de la
28	// séquence. Le rideau lui-même reste peint (phase "text") 1000ms puis met 575ms à se lever
29	// (phase "fadeout", cf. getTextMs/FADEOUT_MS) : il ne révèle donc la scène qu'à 1575ms après
30	// `onCovered`, quand tout le reste est déjà terminé. Pour que cette barre apparaisse EN DERNIER
31	// dans la séquence perçue (au lieu d'être déjà là, toute faite, dès que le rideau se lève comme
32	// tout le reste), son glissement-fondu ne démarre qu'une fois le rideau entièrement levé.
33	const CURTAIN_REVEAL_MS = 1575;
34	
35	/**
36	 * Barre de lecture de l'espace Prévisualisation : play/pause, curseur de progression, vitesse,
37	 * affichage des trajets à vide et import de fichier. Toute la logique vient de
38	 * `useGCodePreview` (voir Index.tsx, qui possède le hook et transmet ses props ici).
39	 *
40	 * Pour l'instant seuls le bouton Play/Pause et le curseur de progression sont branchés ; le reste
41	 * des props (vitesse, trajets à vide, import) restent transmises sans être encore affichées, pour
42	 * ne pas avoir à retoucher Index.tsx quand ce contenu sera ajouté.
43	 *
44	 * Glissement-fondu depuis le bas de l'écran à l'entrée dans l'espace, et inverse à la sortie —
