1	import * as BABYLON from 'babylonjs';
2	
3	/**
4	 * G-code polaire 4 axes de l'Apex : parseur + calque Babylon de prévisualisation.
5	 *
6	 * Ce n'est PAS un G-code cartésien de slicer classique : une seule commande de déplacement,
7	 * `G00 Y<C> X<R> Z<Z> B<B> [E<e>] F<f>`.
8	 *  - X = R : rayon depuis le centre du plateau (mm, ≥ 0).
9	 *  - Y = C : angle du plateau (degrés, absolu, JAMAIS replié modulo 360 — le générateur garde
10	 *    la continuité angulaire, un C > 360 ou négatif est normal).
11	 *  - Z : hauteur (mm). B : inclinaison de la tête vers −R (vers l'axe de rotation), en degrés.
12	 *  - E (optionnel) : position absolue de l'extrudeur. E croissant = dépôt ; E absent ou
13	 *    stationnaire = trajet à vide.
14	 *
15	 * Représentation (cf. `createGCodeLayer`) :
16	 *  - La matière est stockée une fois pour toutes en repère plateau (x = R cos C, z = R sin C,
17	 *    avec le C du moment du dépôt) sous un noeud dont la rotation suit le C courant : plateau
18	 *    et matière tournent strictement ensemble.
19	 *  - La tête reste dans le demi-plan machine fixe (R, 0, Z) ; c'est le plateau qui tourne pour
20	 *    amener la pièce sous elle. R/Z sont déjà compensés du pivot par le générateur (`--pivot`) :
21	 *    on les affiche tels quels.
22	 *  - Tout est interpolé dans l'espace (R, C, Z, B) du firmware, jamais en cartésien : les
23	 *    segments sont subdivisés en angle pour suivre l'arc réellement parcouru, et la position
24	 *    animée entre deux consignes est interpolée en (R, C, Z, B) puis convertie.
25	 *  - Aucune décimation "1 point sur N" (sauts angulaires visibles sur les portions courbes).
26	 */
27	
28	export interface GCodeMove {
29	  r: number;
30	  c: number;
31	  z: number;
32	  b: number;
33	  extruding: boolean;
34	}
35	
36	export interface ParsedGCode {
37	  moves: GCodeMove[];
38	  minZ: number;
39	  maxZ: number;
40	  maxR: number;
41	  minC: number;
42	  maxC: number;
43	  extrudingCount: number;
44	}
45	
46	const DEG2RAD = Math.PI / 180;
47	// Pas angulaire max d'un sous-segment : au-delà, la corde cartésienne s'écarte visiblement de
48	// l'arc réellement décrit par le firmware (qui interpole en C, pas en x/y).
49	const MAX_SUBSEGMENT_DEG = 0.5;
50	/** Au-delà de cette amplitude totale de C, le fichier vient très probablement de la version
51	 * boguée du générateur (C qui dérive de tour en tour au lieu d'osciller dans une plage étroite). */
52	export const SUSPICIOUS_C_RANGE_DEG = 720;
53	
54	const G00_RE = /^G0*0(?![0-9])/i;
55	const WORD_RE = /([XYZBEF])\s*([-+]?(?:\d+\.?\d*|\.\d+))/gi;
56	
57	export function parseGCode(text: string): ParsedGCode {
58	  const moves: GCodeMove[] = [];
59	  let r = 0, c = 0, z = 0, b = 0;
60	  let lastE: number | null = null;
61	  let extrudingCount = 0;
62	
63	  for (const rawLine of text.split(/\r?\n/)) {
64	    const line = rawLine.replace(/\(.*?\)/g, '').replace(/;.*$/, '').trim();
65	    if (!line || !G00_RE.test(line)) continue;
66	
67	    let e: number | null = null;
68	    WORD_RE.lastIndex = 0;
69	    let m: RegExpExecArray | null;
70	    while ((m = WORD_RE.exec(line)) !== null) {
71	      const value = parseFloat(m[2]);
72	      if (Number.isNaN(value)) continue;
73	      switch (m[1].toUpperCase()) {
74	        case 'X': r = value; break;
75	        case 'Y': c = value; break;
76	        case 'Z': z = value; break;
77	        case 'B': b = value; break;
78	        case 'E': e = value; break;
79	      }
80	    }
81	
82	    const extruding = e !== null && lastE !== null && e > lastE + 1e-9;
83	    if (e !== null) lastE = e;
84	    if (extruding) extrudingCount++;
85	    moves.push({ r, c, z, b, extruding });
86	  }
87	
88	  let minZ = Infinity, maxZ = -Infinity, maxR = 0, minC = Infinity, maxC = -Infinity;
89	  for (const mv of moves) {
90	    if (mv.z < minZ) minZ = mv.z;
91	    if (mv.z > maxZ) maxZ = mv.z;
92	    if (mv.r > maxR) maxR = mv.r;
93	    if (mv.c < minC) minC = mv.c;
94	    if (mv.c > maxC) maxC = mv.c;
95	  }
96	  if (!moves.length) { minZ = maxZ = minC = maxC = 0; }
97	
98	  return { moves, minZ, maxZ, maxR, minC, maxC, extrudingCount };
99	}
100	
101	/** Position (R, C, Z, B) interpolée linéairement — comme le firmware — au temps `t` exprimé
102	 * en index de mouvement fractionnaire. */
103	export function stateAt(moves: GCodeMove[], t: number) {
104	  const i = Math.max(0, Math.min(moves.length - 1, Math.floor(t)));
105	  const a = moves[i];
106	  const b = moves[Math.min(moves.length - 1, i + 1)];
107	  const f = Math.max(0, Math.min(1, t - i));
108	  return {
109	    r: a.r + (b.r - a.r) * f,
110	    c: a.c + (b.c - a.c) * f,
111	    z: a.z + (b.z - a.z) * f,
112	    b: a.b + (b.b - a.b) * f,
113	  };
114	}
115	
116	interface PathMesh {
117	  mesh: BABYLON.LinesMesh | null;
118	  /** Nombre d'indices à dessiner une fois le mouvement k terminé. */
119	  cumIndices: Uint32Array;
120	}
121	
122	/** Construit un LinesMesh (repère plateau) contenant tous les mouvements dont `extruding`
123	 * vaut `wantExtruding`, dans l'ordre du fichier. N'importe quel préfixe de la trajectoire
124	 * s'affiche ensuite en changeant simplement `indexCount`, sans reconstruire la géométrie. */
125	function buildPathMesh(
126	  name: string,
127	  parsed: ParsedGCode,
128	  segments: Uint32Array,
129	  wantExtruding: boolean,
130	  colorAt: (z: number, out: BABYLON.Color4) => void,
131	  scene: BABYLON.Scene,
132	): PathMesh {
133	  const { moves } = parsed;
134	  let vertexTotal = 0;
135	  for (let k = 1; k < moves.length; k++) {
136	    if (moves[k].extruding === wantExtruding) vertexTotal += segments[k] + 1;
137	  }
138	
139	  const cumIndices = new Uint32Array(moves.length);
140	  if (vertexTotal === 0) return { mesh: null, cumIndices };
141	
142	  const positions = new Float32Array(vertexTotal * 3);
143	  const colors = new Float32Array(vertexTotal * 4);
144	  const indices = new Uint32Array((vertexTotal - 1) * 2);
145	  const col = new BABYLON.Color4();
146	  let v = 0;
147	  let idx = 0;
148	
149	  for (let k = 1; k < moves.length; k++) {
150	    const cur = moves[k];
151	    if (cur.extruding === wantExtruding) {
152	      const prev = moves[k - 1];
153	      const n = segments[k];
154	      for (let s = 0; s <= n; s++) {
155	        const f = s / n;
156	        const r = prev.r + (cur.r - prev.r) * f;
157	        const c = (prev.c + (cur.c - prev.c) * f) * DEG2RAD;
158	        const z = prev.z + (cur.z - prev.z) * f;
159	        positions[v * 3] = r * Math.cos(c);
160	        positions[v * 3 + 1] = z;
161	        positions[v * 3 + 2] = r * Math.sin(c);
162	        colorAt(z, col);
163	        colors[v * 4] = col.r;
164	        colors[v * 4 + 1] = col.g;
165	        colors[v * 4 + 2] = col.b;
166	        colors[v * 4 + 3] = col.a;
167	        if (s > 0) {
168	          indices[idx++] = v - 1;
169	          indices[idx++] = v;
170	        }
171	        v++;
172	      }
173	    }
174	    cumIndices[k] = idx;
175	  }
176	
177	  const mesh = new BABYLON.LinesMesh(name, scene, null, null, undefined, true, true);
178	  const data = new BABYLON.VertexData();
179	  data.positions = positions;
180	  data.colors = colors;
181	  data.indices = indices.subarray(0, idx);
182	  data.applyToMesh(mesh);
183	  // Tant que `indexCount` couvre toute la géométrie, Babylon traite le sous-maillage comme
184	  // « global » et lui prête la boîte englobante du maillage ; dès qu'on n'en affiche qu'un
185	  // préfixe, il lit sa boîte propre — jamais créée, d'où un crash dans le tri des objets
186	  // transparents qui arrêtait la boucle de rendu. On lui en donne une une fois pour toutes :
187	  // celle de la trajectoire complète, qui englobe n'importe quel préfixe (pas de
188	  // `refreshBoundingInfo`, qui reparcourrait les indices à chaque rotation du plateau).
189	  const { minimum, maximum } = mesh.getBoundingInfo();
190	  mesh.subMeshes[0].setBoundingInfo(new BABYLON.BoundingInfo(minimum.clone(), maximum.clone()));
191	  mesh.isPickable = false;
192	  mesh.alwaysSelectAsActiveMesh = true;
193	  return { mesh, cumIndices };
194	}
195	
196	export interface GCodeLayer {
197	  load(parsed: ParsedGCode): void;
198	  /** Position de lecture, en index de mouvement fractionnaire. */
199	  setTime(t: number): void;
200	  setShowTravel(show: boolean): void;
201	  setEnabled(enabled: boolean): void;
202	  /** Rotation courante du plateau autour de Y (radians, repère Babylon), 0 sans G-code. */
203	  getPlateRotation(): number;
204	  dispose(): void;
205	}
206	
207	/** Préfixe de nom de tous les maillages du calque (cf. exclusion de la capture du flou). */
208	export const GCODE_MESH_PREFIX = 'gcode';
209	
210	/**
211	 * Calque de prévisualisation G-code posé dans une scène existante. `parent` est le repère du
212	 * plateau (origine au centre de sa surface) : Z = 0 du G-code y correspond.
213	 */
214	export function createGCodeLayer(
215	  scene: BABYLON.Scene,
216	  parent: BABYLON.TransformNode,
217	  /** Appelé à chaque mise à jour de la rotation du plateau (radians), pour y caler du décor. */
218	  onPlateRotation?: (rotationY: number) => void,
219	): GCodeLayer {
220	  const root = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}Root`, scene);
221	  root.parent = parent;
222	  root.setEnabled(false);
223	
224	  // Repère tournant du plateau : toute la matière déposée en est enfant.
225	  const plateNode = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}Plate`, scene);
226	  plateNode.parent = root;
227	
228	  // Tête : pointe de buse à l'origine du noeud, corps qui monte le long de +Y local ; le noeud
229	  // est ensuite orienté pour que ce corps penche de B vers −R.
230	  const headNode = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}Head`, scene);
231	  headNode.parent = root;
232	  headNode.rotationQuaternion = BABYLON.Quaternion.Identity();
233	  const nozzleMat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}NozzleMat`, scene);
234	  nozzleMat.diffuseColor = new BABYLON.Color3(1, 0.55, 0.05);
235	  nozzleMat.emissiveColor = new BABYLON.Color3(0.35, 0.17, 0);
236	  const nozzle = BABYLON.MeshBuilder.CreateCylinder(`${GCODE_MESH_PREFIX}Nozzle`, { diameterTop: 7, diameterBottom: 0.6, height: 9, tessellation: 20 }, scene);
237	  nozzle.position.y = 4.5;
238	  nozzle.material = nozzleMat;
239	  nozzle.parent = headNode;
240	  const bodyMat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}HeadBodyMat`, scene);
241	  bodyMat.diffuseColor = new BABYLON.Color3(0.55, 0.58, 0.64);
242	  bodyMat.alpha = 0.55;
243	  const body = BABYLON.MeshBuilder.CreateCylinder(`${GCODE_MESH_PREFIX}HeadBody`, { diameter: 14, height: 26, tessellation: 24 }, scene);
244	  body.position.y = 9 + 13;
245	  body.material = bodyMat;
246	  body.parent = headNode;
247	  nozzle.isPickable = false;
248	  body.isPickable = false;
249	  headNode.setEnabled(false);
250	
251	  let parsed: ParsedGCode | null = null;
252	  let segments = new Uint32Array(0);
253	  let extruded: PathMesh | null = null;
254	  let travel: PathMesh | null = null;
255	  let time = 0;
256	  let showTravel = false;
257	
258	  const up = BABYLON.Vector3.Up();
259	  const headDir = new BABYLON.Vector3();
260	
261	  const apply = () => {
262	    if (!parsed || parsed.moves.length === 0) return;
263	    const last = parsed.moves.length - 1;
264	    const t = Math.max(0, Math.min(last, time));
265	    const state = stateAt(parsed.moves, t);
266	
267	    // Dans le repère main gauche de Babylon, rotation.y = ψ envoie un angle local θ
268	    // (x = cos θ, z = sin θ) sur θ − ψ. Avec ψ = C courant, un point déposé à C_dépôt est à
269	    // l'angle machine C_dépôt − C : pile sous la tête (angle 0) au moment de son dépôt, puis
270	    // entraîné avec le plateau. Le signe opposé ferait apparaître la pièce en miroir.
271	    plateNode.rotation.y = state.c * DEG2RAD;
272	    onPlateRotation?.(plateNode.rotation.y);
273	
274	    headNode.position.set(state.r, state.z, 0);
275	    const bRad = state.b * DEG2RAD;
276	    headDir.set(-Math.sin(bRad), Math.cos(bRad), 0);
277	    BABYLON.Quaternion.FromUnitVectorsToRef(up, headDir, headNode.rotationQuaternion!);
278	
279	    // Préfixe affiché : mouvements terminés + fraction du mouvement en cours, au sous-segment
280	    // près (cohérent avec l'interpolation en C).
281	    const i = Math.floor(t);
282	    const next = Math.min(last, i + 1);
