file.content:
.container {
  position: fixed;
  top: 20px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  z-index: 1000;
  pointer-events: none;
}

.toolbar {
  display: flex;
  align-items: center;
  pointer-events: auto;
  transition: background 0.3s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.3s cubic-bezier(0.4, 0, 0.2, 1);

  background: rgba(10, 15, 26, 0.25);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  border: none;
  box-shadow: 0 12px 40px 0 rgba(0, 0, 0, 0.35), 0 4px 16px 0 rgba(0, 0, 0, 0.25);
}

.topToolbar {
  padding: 8px 16px;
  border-radius: 33px;
  gap: 5.33px;
  position: relative;
  overflow: visible !important;
}

.bottomToolbar {
  position: relative;
  padding: 6px 10px;
  border-radius: 22px;
  gap: 6px;
  overflow: visible !important;
}

// Slot du mode modélisation : occupe tout le conteneur commun une fois déformé, et
// dispose les boutons CAD injectés par portail (voir Sidebar.tsx / ModelingSidebar.tsx)
// exactement comme l'ancien `.opsBarInner`.
.modelingSlot {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 6px;
}

.button {
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  color: rgba(255, 255, 255, 0.85);
  cursor: pointer;
  transition: all 0.2s ease;
  outline: none;
  position: relative;
  z-index: 2;

  &:hover:not(:disabled) {
    color: rgba(255, 255, 255, 1);
    background: rgba(255, 255, 255, 0.18);
  }

  &:disabled {
    opacity: 0.3;
    cursor: not-allowed;
  }
}

.topButton {
  height: 42px;
  padding: 0 14px;
  border-radius: 14px;
  gap: 8px;

  &.active {
    color: #00f0ff;
  }
}

.topButtonLabel {
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
}

.sliceButton {
  background: rgba(0, 240, 255, 0.15);
  color: #00f0ff;
  border: none;

  &:hover {
    background: rgba(0, 240, 255, 0.25) !important;
  }
}

.configButton {
  color: #a78bfa;
  &:hover {
    background: rgba(167, 139, 250, 0.15) !important;
  }
}

.logoContainer {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  padding: 2px;

