toolUseResult.originalFile:
// Barre de lecture G-code (espace Prévisualisation) : même verre que les autres panneaux
// flottants (.previewPanelUpper/.previewPanelLower dans CategoriesSidebar.module.scss,
// .categoriesToolbar) pour rester cohérente avec le reste du chrome. Rendue comme enfant flex de
// la même rangée que le statut du plateau (cf. Index.tsx) plutôt que positionnée
// indépendamment : elle occupe l'espace restant à droite de la pastille de statut, exactement là
// où se trouvait le rectangle vide.
//
// Contenu : bouton Play/Pause aligné à gauche puis, dans l'espace restant, le curseur de
// prévisualisation (cf. GCodePreviewBar.tsx). Hauteur volontairement plus grande que la pastille
// de statut voisine (~32px avec son padding) plutôt qu'égale à elle.
.bar {
  position: relative;
  flex: 0 0 80%;
  min-width: 0;
  height: 40px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 12px;
  border-radius: 14px;
  border: none;
  isolation: isolate;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  pointer-events: auto;

  &::before {
    content: '';
    position: absolute;
    inset: 0;
    background: rgba(10, 15, 26, 0.25);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
  }
}

// Bouton Play/Pause : rond, aligné à gauche de la barre (premier enfant flex), même teinte de
// verre que le fond de la barre mais légèrement plus opaque pour se détacher comme un vrai bouton.
// Sans bordure ni contour, comme tous les autres boutons du slicer (cf. CategoriesSidebar.module.scss).
.playButton {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  border: none;
  outline: none;
  background: rgba(255, 255, 255, 0.06);
  color: #e4e4e7;
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease;

  // Le trait vertical de Pause (`fill-current`, 14px) atterrit visuellement décentré vers la
  // gauche par rapport au triangle de Play : recentrage optique, pas géométrique.
  svg {
    margin-left: 1px;
  }

  &:hover:not(:disabled) {
    background: rgba(255, 255, 255, 0.12);
    color: #00f0ff;
  }

  &:disabled {
    opacity: 0.35;
    cursor: default;
  }
}

// Curseur de prévisualisation : occupe l'espace restant à droite du bouton Play. Zone de
// interaction plus haute que le rail visuel (comme un <input type="range">) pour rester facile à
// saisir, le rail (scindé en deux segments) et la poignée n'étant que des enfants centrés dedans.
// --handle-gap : espace laissé de part et d'autre de la poignée, entre elle et chacun des deux
// segments — jamais de ligne touchant directement le point de clic (cf. maquette).
.track {
  --handle-gap: 5px;
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  height: 100%;
  display: flex;
  align-items: center;
  cursor: pointer;
  touch-action: none;

  &[aria-disabled='true'] {
    cursor: default;
  }
}

// Segment parcouru (avant la poignée) et segment restant (après), strictement séparés — plus de
// conteneur .trackRail commun, puisque le fond et le remplissage doivent chacun s'arrêter avant
// la poignée plutôt que se chevaucher sous elle.
.trackFill,
.trackRemainder {
  position: absolute;
  top: 50%;
  height: 3px;
  border-radius: 2px;
  transform: translateY(-50%);
}

.trackFill {
  left: 0;
  background: #00f0ff;
  // La poignée porte son propre halo lumineux ; le segment reste net pour ne pas le dupliquer.
}

.trackRemainder {
  right: 0;
  background: rgba(255, 255, 255, 0.12);
}

// Poignée : rectangle arrondi (pilule) plutôt qu'un simple point, avec un flou de fond qui la
// détache du rail — cohérent avec le verre du reste du chrome (cf. .bar) plutôt qu'un disque plein.
.trackHandle {
  position: absolute;
  top: 50%;
  width: 8px;
  height: 18px;
  border-radius: 4px;
  background: rgba(0, 240, 255, 0.9);
  backdrop-filter: blur(2px);
  -webkit-backdrop-filter: blur(2px);
  box-shadow: 0 0 10px 2px rgba(0, 240, 255, 0.65), 0 0 2px 0 rgba(0, 0, 0, 0.4);
  transform: translate(-50%, -50%);
  pointer-events: none;
  transition: box-shadow 0.15s ease;
}

.track:hover .trackHandle {
  box-shadow: 0 0 14px 3px rgba(0, 240, 255, 0.9), 0 0 2px 0 rgba(0, 0, 0, 0.4);
}

