  const seek = (value: number) => {
    setIsPlaying(false);
    tRef.current = value;
    setT(value);
    dispatchTime(value);
  };

  /** Lecture/pause ; repart du début si la lecture est au bout. */
  const togglePlay = () => {
    const parsed = parsedRef.current;
    if (!parsed) return;
    if (!isPlaying && tRef.current >= parsed.moves.length - 1) seek(0);
