  const openFilePicker = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = GCODE_ACCEPT;
    input.onchange = () => {
      const file = input.files?.[0];
      if (file) loadFile(file);
    };
    input.click();
  };

