toolUseResult.originalFile:
// Barre de lecture G-code (espace Prévisualisation) : même verre que les autres panneaux
// flottants (.previewPanelUpper/.previewPanelLower dans CategoriesSidebar.module.scss,
// .categoriesToolbar) pour rester cohérente avec le reste du chrome. Rendue comme enfant flex de
// la même rangée que le statut du plateau (cf. Index.tsx) plutôt que positionnée
// indépendamment : elle occupe l'espace restant à droite de la pastille de statut, exactement là
// où se trouvait le rectangle vide.
//
// Contenu : bouton Play/Pause aligné à gauche puis, dans l'espace restant, le curseur de
// prévisualisation (cf. GCodePreviewBar.tsx). Hauteur volontairement plus grande que la pastille
// de statut voisine (~32px avec son padding) plutôt qu'égale à elle.
.bar {
  position: relative;
  flex: 0 0 80%;
  min-width: 0;
  height: 40px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 12px;
  border-radius: 14px;
  border: none;
  isolation: isolate;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  pointer-events: auto;

  &::before {
    content: '';
    position: absolute;
    inset: 0;
    background: rgba(10, 15, 26, 0.25);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
  }
}

// Bouton Play/Pause : rond, aligné à gauche de la barre (premier enfant flex), même teinte de
// verre que le fond de la barre mais légèrement plus opaque pour se détacher comme un vrai bouton.
// Contour transparent au repos qui ne devient visible qu'au survol (avec le fond qui s'éclaircit),
// comme .itemRow/.clickableRow dans CategoriesSidebar.module.scss — jamais de contour fixe, jamais
// de couleur d'accent au survol.
.playButton {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  border: 1px solid transparent;
  outline: none;
  background: rgba(255, 255, 255, 0.06);
  color: #e4e4e7;
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease;

  // Le trait vertical de Pause (`fill-current`, 14px) atterrit visuellement décentré vers la
  // gauche par rapport au triangle de Play : recentrage optique, pas géométrique.
  svg {
    margin-left: 1px;
  }

  &:hover:not(:disabled) {
    background: rgba(255, 255, 255, 0.12);
    border-color: rgba(255, 255, 255, 0.2);
  }

  &:disabled {
    opacity: 0.35;
    cursor: default;
  }
}

// Curseur de prévisualisation : occupe l'espace restant à droite du bouton Play. Zone de
// interaction plus haute que le rail visuel (comme un <input type="range">) pour rester facile à
// saisir, le rail (scindé en deux segments) et la poignée n'étant que des enfants centrés dedans.
// --handle-gap : espace laissé de part et d'autre de la poignée, entre elle et chacun des deux
// segments — jamais de ligne touchant directement le point de clic (cf. maquette).
.track {
  --handle-gap: 10px;
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  height: 100%;
  display: flex;
  align-items: center;
  cursor: pointer;
  touch-action: none;

  &[aria-disabled='true'] {
    cursor: default;
  }
}

// Segment parcouru (avant la poignée) et segment restant (après), strictement séparés — plus de
// conteneur .trackRail commun, puisque le fond et le remplissage doivent chacun s'arrêter avant
// la poignée plutôt que se chevaucher sous elle.
.trackFill,
.trackRemainder {
  position: absolute;
  top: 50%;
  height: 3px;
  border-radius: 2px;
  transform: translateY(-50%);
}

.trackFill {
  left: 0;
  background: #00f0ff;
}

.trackRemainder {
  right: 0;
  background: rgba(255, 255, 255, 0.12);
}

// Poignée : rectangle arrondi (pilule) plutôt qu'un simple point, en verre dépoli — même recette
// que .bar (fond translucide + flou) plutôt qu'un disque plein ou lumineux. Pas de halo externe :
// seule une ombre portée neutre la détache du rail, comme .playButton au repos.
.trackHandle {
  position: absolute;
  top: 50%;
  width: 10px;
  height: 18px;
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.18);
  border: 1px solid rgba(255, 255, 255, 0.3);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  box-shadow: 0 2px 6px 0 rgba(0, 0, 0, 0.4);
  transform: translate(-50%, -50%);
  pointer-events: none;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}

.track:hover .trackHandle {
  background: rgba(255, 255, 255, 0.26);
  border-color: rgba(255, 255, 255, 0.4);
}

import React, { useCallback, useLayoutEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Play, Pause } from 'lucide-react';
import { type GCodeFileInfo } from '@/hooks/use-gcode-preview';
import styles from './GCodePreviewBar.module.scss';

interface GCodePreviewBarProps {
  /** Espace Prévisualisation affiché. Nécessaire mais pas suffisant pour afficher la barre : elle
   * reste en plus masquée tant qu'aucun G-code n'est chargé ni en cours de chargement (cf.
   * `fileInfo`/`isLoading`). */
  active: boolean;
  fileInfo: GCodeFileInfo | null;
  isLoading: boolean;
  t: number;
  lastIndex: number;
  isPlaying: boolean;
  togglePlay: () => void;
  seek: (value: number) => void;
  speed: number;
  setSpeed: (speed: number) => void;
  showTravel: boolean;
  setShowTravel: (show: boolean) => void;
  openFilePicker: () => void;
}

// `active` (isPreviewActive) devient vrai dans `onCovered` (cf. Sidebar.tsx), à l'instant précis
// où le rideau plein écran (SpaceTransitionOverlay) vient de finir de se peindre — PAS quand il a
// fini de se lever. À ce même instant démarrent aussi, tous masqués par le rideau : la mitose
// pilule → panneaux de CategoriesSidebar (PREVIEW_MORPH_MS = 1370ms) et le déplacement de la barre
// d'aide TopRightMenu (RESHAPE_DURATION = 1100ms) — les deux plus longues animations de la
// séquence. Le rideau lui-même reste peint (phase "text") 1000ms puis met 575ms à se lever
// (phase "fadeout", cf. getTextMs/FADEOUT_MS) : il ne révèle donc la scène qu'à 1575ms après
// `onCovered`, quand tout le reste est déjà terminé. Pour que cette barre apparaisse EN DERNIER
// dans la séquence perçue (au lieu d'être déjà là, toute faite, dès que le rideau se lève comme
// tout le reste), son glissement-fondu ne démarre qu'une fois le rideau entièrement levé.
const CURTAIN_REVEAL_MS = 1575;

/**
 * Barre de lecture de l'espace Prévisualisation : play/pause, curseur de progression, vitesse,
 * affichage des trajets à vide et import de fichier. Toute la logique vient de
 * `useGCodePreview` (voir Index.tsx, qui possède le hook et transmet ses props ici).
 *
 * Pour l'instant seuls le bouton Play/Pause et le curseur de progression sont branchés ; le reste
 * des props (vitesse, trajets à vide, import) restent transmises sans être encore affichées, pour
 * ne pas avoir à retoucher Index.tsx quand ce contenu sera ajouté.
 *
 * N'apparaît que si un G-code est chargé ou en cours de chargement (`fileInfo`/`isLoading`) — pas
 * seulement parce que l'espace Prévisualisation est affiché : sans trajectoire à montrer, la barre
 * de lecture n'a rien à piloter et reste masquée comme le reste du contenu ci-dessus.
 *
 * Glissement-fondu depuis le bas de l'écran à l'entrée dans l'espace, et inverse à la sortie —
 * comme le panneau du bas de CategoriesSidebar (cf. FROM_PREVIEW_FADE_MS), mais vertical plutôt
 * qu'horizontal puisque cette barre vient du bord bas de l'écran plutôt que du bord gauche.
 * Retardée (CURTAIN_REVEAL_MS) pour apparaître en tout dernier, une fois le rideau levé et le
 * reste de la séquence terminé — jamais à la sortie de l'espace, où elle disparaît normalement.
 * Cette même transition sert aussi à l'apparition/disparition au chargement/déchargement d'un
 * G-code une fois l'espace déjà affiché, sans le délai CURTAIN_REVEAL_MS (non pertinent hors de
 * la séquence d'entrée dans l'espace, cf. `visible` ci-dessous).
 */
export const GCodePreviewBar: React.FC<GCodePreviewBarProps> = ({
  active,
  fileInfo,
  isLoading,
  t,
  lastIndex,
  isPlaying,
  togglePlay,
  seek,
}) => {
  const trackRef = useRef<HTMLDivElement>(null);
  const visible = active && (!!fileInfo || isLoading);

  // CURTAIN_REVEAL_MS ne doit retarder que la toute première apparition de la barre après l'entrée
  // dans l'espace (rideau qui se lève) — pas une réapparition ultérieure au chargement d'un
  // G-code alors que l'espace est déjà affiché depuis longtemps, qui doit être immédiate.
  const revealDelayMs = useRef(CURTAIN_REVEAL_MS);
  useLayoutEffect(() => {
    if (!active) revealDelayMs.current = CURTAIN_REVEAL_MS;
  }, [active]);
  const delay = revealDelayMs.current;
  if (visible) revealDelayMs.current = 0;
  // Pas de mouvement chargé : curseur figé au tout début plutôt que masqué, la barre reste posée.
  const ratio = lastIndex > 0 ? Math.min(1, Math.max(0, t / lastIndex)) : 0;

  const seekFromClientX = useCallback((clientX: number) => {
    const track = trackRef.current;
    if (!track || lastIndex <= 0) return;
    const rect = track.getBoundingClientRect();
    const localRatio = rect.width > 0 ? (clientX - rect.left) / rect.width : 0;
    seek(Math.round(Math.min(1, Math.max(0, localRatio)) * lastIndex));
  }, [lastIndex, seek]);

  // Glisser depuis n'importe où sur la piste, y compris hors de son rectangle une fois le drag
  // commencé (pointer capture) : convention standard des curseurs de lecture.
  const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (lastIndex <= 0) return;
    e.currentTarget.setPointerCapture(e.pointerId);
    seekFromClientX(e.clientX);
  };
  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (e.buttons !== 1) return;
    seekFromClientX(e.clientX);
  };

  return (
    <AnimatePresence>
      {visible && (
        <motion.div
          className={styles.bar}
          data-apex-chrome-panel
          initial={{ opacity: 0, y: 40 }}
          animate={{ opacity: 1, y: 0, transition: { duration: 0.4, delay: delay / 1000, ease: [0.16, 1, 0.3, 1] } }}
          exit={{ opacity: 0, y: 40, transition: { duration: 0.4, ease: [0.16, 1, 0.3, 1] } }}
        >
          <button
            type="button"
            className={styles.playButton}
            onClick={togglePlay}
            disabled={lastIndex <= 0}
            aria-label={isPlaying ? 'Pause' : 'Lecture'}
            aria-pressed={isPlaying}
          >
            {isPlaying ? <Pause size={14} className="fill-current" /> : <Play size={14} className="fill-current" />}
          </button>

          <div
            ref={trackRef}
            className={styles.track}
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            role="slider"
            aria-label="Ligne de prévisualisation"
            aria-valuemin={0}
            aria-valuemax={lastIndex}
            aria-valuenow={Math.round(t)}
            aria-disabled={lastIndex <= 0}
          >
            <div
              className={styles.trackFill}
              style={{ right: `calc(${100 - ratio * 100}% + var(--handle-gap))` }}
            />
            <div
              className={styles.trackRemainder}
              style={{ left: `calc(${ratio * 100}% + var(--handle-gap))` }}
            />
            <div className={styles.trackHandle} style={{ left: `${ratio * 100}%` }} />
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

