1	import hoverSoundSrc from "@/assets/sounds/hover.mp3";
2	import clickSoundSrc from "@/assets/sounds/click.mp3";
3	import spacePreparationSoundSrc from "@/assets/sounds/space-preparation.mp3";
4	import spacePreviewSoundSrc from "@/assets/sounds/space-preview.mp3";
5	import spaceModelingSoundSrc from "@/assets/sounds/space-modeling.mp3";
6	
7	// Lecture via la Web Audio API plutôt que des HTMLAudioElement : chaque son
8	// est décodé UNE fois en AudioBuffer, puis chaque appel crée sa propre
9	// AudioBufferSourceNode. Les lectures qui se chevauchent (survol rapide,
10	// clic pendant un hover, changement d'onglet...) se mixent donc et vont
11	// toutes jusqu'au bout, sans latence de chargement ni rejet aléatoire de
12	// play() comme avec un `new Audio()` à chaque appel.
13	const SOUND_FILES = {
14	  hover: hoverSoundSrc,
15	  click: clickSoundSrc,
16	  spacePreparation: spacePreparationSoundSrc,
17	  spacePreview: spacePreviewSoundSrc,
18	  spaceModeling: spaceModelingSoundSrc,
19	} as const;
20	
21	export type UiSoundName = keyof typeof SOUND_FILES;
22	
23	const VOLUME: Record<UiSoundName, number> = {
24	  hover: 0.35,
25	  click: 0.5,
26	  spacePreparation: 0.5,
27	  spacePreview: 0.5,
28	  spaceModeling: 0.5,
29	};
30	
31	// Début de lecture (en secondes) dans le fichier : les sons d'espace ont un
32	// blanc/une attaque en tête qu'on saute pour qu'ils collent au clic.
33	const START_OFFSET: Partial<Record<UiSoundName, number>> = {
34	  spacePreparation: 0.3,
35	  spacePreview: 0.3,
36	  spaceModeling: 0.3,
37	};
38	
39	const MUTE_STORAGE_KEY = "apex-ui-sound-muted";
40	
41	// Coupés par défaut : seule la présence explicite de "false" dans le
42	// localStorage (l'utilisateur a déjà réactivé le son une fois) désactive le
43	// mute. Toute autre valeur (absente, "true", corrompue) => muet.
44	function readStoredMuted(): boolean {
45	  try {
46	    return localStorage.getItem(MUTE_STORAGE_KEY) !== "false";
47	  } catch {
48	    return true;
49	  }
50	}
51	
52	let muted = readStoredMuted();
53	const listeners = new Set<(muted: boolean) => void>();
54	
55	export function isUiSoundMuted() {
56	  return muted;
57	}
58	
59	export function setUiSoundMuted(next: boolean) {
60	  muted = next;
61	  try {
62	    localStorage.setItem(MUTE_STORAGE_KEY, String(next));
63	  } catch {
64	    // no-op : localStorage indisponible (navigation privée, quota...).
65	  }
66	  listeners.forEach((listener) => listener(muted));
67	}
68	
69	export function toggleUiSoundMuted() {
70	  setUiSoundMuted(!muted);
71	}
72	
73	export function subscribeUiSoundMuted(listener: (muted: boolean) => void) {
74	  listeners.add(listener);
75	  return () => {
76	    listeners.delete(listener);
77	  };
78	}
79	
80	type AudioContextCtor = typeof AudioContext;
81	
82	let audioContext: AudioContext | null = null;
83	const buffers: Partial<Record<UiSoundName, AudioBuffer>> = {};
84	let buffersLoading: Promise<void> | null = null;
85	
86	function getAudioContext(): AudioContext | null {
87	  if (audioContext) return audioContext;
88	  if (typeof window === "undefined") return null;
89	  const Ctor: AudioContextCtor | undefined =
90	    window.AudioContext ??
91	    (window as unknown as { webkitAudioContext?: AudioContextCtor }).webkitAudioContext;
92	  if (!Ctor) return null;
93	  audioContext = new Ctor();
94	  return audioContext;
95	}
96	
97	function loadBuffers(context: AudioContext) {
98	  buffersLoading ??= Promise.all(
99	    (Object.entries(SOUND_FILES) as [UiSoundName, string][]).map(async ([name, src]) => {
100	      try {
101	        const response = await fetch(src);
102	        const data = await response.arrayBuffer();
103	        buffers[name] = await context.decodeAudioData(data);
104	      } catch {
105	        // no-op : un son manquant ne doit pas empêcher les autres de charger.
106	      }
107	    }),
108	  ).then(() => {});
109	  return buffersLoading;
110	}
