  cumIndices: Uint32Array;
  /** Nombre d'indices par sous-segment : granularité de l'affichage d'un mouvement partiel. */
  indicesPerStep: number;
}

/** Section du cordon déposé (mm) : largeur de part et d'autre de la trajectoire, et épaisseur le
 * long de l'axe de la buse. Pas d'information de largeur/couche dans ce G-code : valeurs
 * nominales. */
export const BEAD_WIDTH_MM = 0.6;
export const BEAD_HEIGHT_MM = 0.3;
/** Nombre de facettes de la section du cordon. */
const TUBE_SIDES = 6;

/** Donne à un sous-maillage affiché par préfixe (`indexCount`) une boîte englobante propre. */
function finalizePathMesh(mesh: BABYLON.Mesh) {
  // Tant que `indexCount` couvre toute la géométrie, Babylon traite le sous-maillage comme
  // « global » et lui prête la boîte englobante du maillage ; dès qu'on n'en affiche qu'un
  // préfixe, il lit sa boîte propre — jamais créée, d'où un crash dans le tri des objets
  // transparents qui arrêtait la boucle de rendu. On lui en donne une une fois pour toutes :
  // celle de la trajectoire complète, qui englobe n'importe quel préfixe (pas de
  // `refreshBoundingInfo`, qui reparcourrait les indices à chaque rotation du plateau).
  const { minimum, maximum } = mesh.getBoundingInfo();
  mesh.subMeshes[0].setBoundingInfo(new BABYLON.BoundingInfo(minimum.clone(), maximum.clone()));
  mesh.isPickable = false;
  mesh.alwaysSelectAsActiveMesh = true;
}

/**
 * Construit le cordon de matière (repère plateau) : un tube à section elliptique le long de tous
 * les mouvements qui extrudent, dans l'ordre du fichier. La section est orientée selon l'axe de
 * la buse au moment du dépôt (écrasée le long de cet axe, BEAD_HEIGHT_MM) et centrée une
 * demi-épaisseur sous la pointe de buse, là où la matière est réellement posée. Les mouvements
 * extrudants consécutifs partagent leurs anneaux de jonction : un seul tube continu par suite
 * ininterrompue de dépôts. Comme pour les lignes, n'importe quel préfixe s'affiche en changeant
 * `indexCount`, sans reconstruire la géométrie.
 */
function buildBeadMesh(
  name: string,
  parsed: ParsedGCode,
  segments: Uint32Array,
  colorAt: (z: number, out: BABYLON.Color4) => void,
  material: BABYLON.Material,
  scene: BABYLON.Scene,
): PathMesh {
  const { moves } = parsed;
  const indicesPerStep = TUBE_SIDES * 6;
  const cumIndices = new Uint32Array(moves.length);

  let capacity = 0;
  for (let k = 1; k < moves.length; k++) {
    if (moves[k].extruding) capacity += segments[k] + 1;
  }
  if (capacity === 0) return { mesh: null, cumIndices, indicesPerStep };

  // Passe 1 : échantillons le long de la trajectoire — centre du cordon, axe de buse, mouvement
  // propriétaire et début de tube (pas de sous-segment qui le relie au précédent).
  const centers = new Float32Array(capacity * 3);
  const axes = new Float32Array(capacity * 3);
  const owner = new Uint32Array(capacity);
  const stripStart = new Uint8Array(capacity);
  const tip = { r: 0, z: 0 };
  const halfH = BEAD_HEIGHT_MM / 2;
  let count = 0;

  for (let k = 1; k < moves.length; k++) {
    const cur = moves[k];
    if (!cur.extruding) continue;
    const prev = moves[k - 1];
    // Le mouvement précédent était déjà un dépôt dessiné : son dernier échantillon est notre
    // point de départ, on prolonge le même tube au lieu d'en ouvrir un nouveau.
    const continues = k > 1 && prev.extruding;
    const n = segments[k];
    for (let s = continues ? 1 : 0; s <= n; s++) {
      const f = s / n;
      const c = (prev.c + (cur.c - prev.c) * f) * DEG2RAD;
      const b = (prev.b + (cur.b - prev.b) * f) * DEG2RAD;
      nozzleTip(prev.r + (cur.r - prev.r) * f, prev.z + (cur.z - prev.z) * f, b, tip);
      const cosC = Math.cos(c), sinC = Math.sin(c);
      // Axe de buse (vers le haut de la tête) en repère plateau : (sin B, cos B) dans le
      // demi-plan machine, dont la direction radiale est à l'angle C du dépôt.
      const ax = Math.sin(b) * cosC, ay = Math.cos(b), az = Math.sin(b) * sinC;
      centers[count * 3] = tip.r * cosC - ax * halfH;
      centers[count * 3 + 1] = tip.z - ay * halfH;
      centers[count * 3 + 2] = tip.r * sinC - az * halfH;
      axes[count * 3] = ax;
      axes[count * 3 + 1] = ay;
      axes[count * 3 + 2] = az;
      owner[count] = k;
      stripStart[count] = s === 0 ? 1 : 0;
      count++;
    }
  }

  // Passe 2 : un anneau elliptique par échantillon, dans le repère (côté, axe de buse)
  // perpendiculaire à la tangente, puis les quads entre anneaux consécutifs d'un même tube.
  const positions = new Float32Array(count * TUBE_SIDES * 3);
  const normals = new Float32Array(count * TUBE_SIDES * 3);
  const colors = new Float32Array(count * TUBE_SIDES * 4);
  const indices = new Uint32Array(count * indicesPerStep);
  const ringCos = new Float32Array(TUBE_SIDES);
  const ringSin = new Float32Array(TUBE_SIDES);
  for (let i = 0; i < TUBE_SIDES; i++) {
    ringCos[i] = Math.cos((i / TUBE_SIDES) * Math.PI * 2);
    ringSin[i] = Math.sin((i / TUBE_SIDES) * Math.PI * 2);
  }
  const halfW = BEAD_WIDTH_MM / 2;
  const col = new BABYLON.Color4();
  // Dernière tangente valide : reprise pour les échantillons confondus (mouvement d'extrusion
  // seule, sans déplacement), dont la tangente locale est nulle.
  let tx = 1, ty = 0, tz = 0;
  let idx = 0;

  for (let j = 0; j < count; j++) {
    const p = j * 3;
    const hasPrev = !stripStart[j];
    const hasNext = j + 1 < count && !stripStart[j + 1];
    const from = hasPrev ? p - 3 : p;
    const to = hasNext ? p + 3 : p;
    let dx = centers[to] - centers[from];
    let dy = centers[to + 1] - centers[from + 1];
    let dz = centers[to + 2] - centers[from + 2];
    let len = Math.hypot(dx, dy, dz);
    if (len > 1e-6) {
      tx = dx / len; ty = dy / len; tz = dz / len;
    }

    // Axe de buse rendu orthogonal à la tangente ; s'il lui est parallèle (déplacement le long
    // de la buse), n'importe quelle perpendiculaire convient.
    let ux = axes[p], uy = axes[p + 1], uz = axes[p + 2];
    const dot = ux * tx + uy * ty + uz * tz;
    ux -= dot * tx; uy -= dot * ty; uz -= dot * tz;
    len = Math.hypot(ux, uy, uz);
    if (len < 1e-6) {
      ux = -ty; uy = tx; uz = 0;
      len = Math.hypot(ux, uy, uz);
      if (len < 1e-6) { ux = 0; uy = -tz; uz = ty; len = Math.hypot(uy, uz); }
    }
    ux /= len; uy /= len; uz /= len;
    // Côté = tangente × axe.
    dx = ty * uz - tz * uy;
    dy = tz * ux - tx * uz;
    dz = tx * uy - ty * ux;

    colorAt(centers[p + 1] + halfH, col);
    for (let i = 0; i < TUBE_SIDES; i++) {
      const v = j * TUBE_SIDES + i;
      const cs = ringCos[i], sn = ringSin[i];
      positions[v * 3] = centers[p] + dx * halfW * cs + ux * halfH * sn;
      positions[v * 3 + 1] = centers[p + 1] + dy * halfW * cs + uy * halfH * sn;
      positions[v * 3 + 2] = centers[p + 2] + dz * halfW * cs + uz * halfH * sn;
      // Normale d'ellipse : gradient (cos/a, sin/b) dans le repère (côté, axe).
      let nx = dx * cs / halfW + ux * sn / halfH;
      let ny = dy * cs / halfW + uy * sn / halfH;
      let nz = dz * cs / halfW + uz * sn / halfH;
      const nl = Math.hypot(nx, ny, nz) || 1;
      nx /= nl; ny /= nl; nz /= nl;
      normals[v * 3] = nx;
      normals[v * 3 + 1] = ny;
      normals[v * 3 + 2] = nz;
      colors[v * 4] = col.r;
      colors[v * 4 + 1] = col.g;
      colors[v * 4 + 2] = col.b;
      colors[v * 4 + 3] = 1;
    }

    if (hasPrev) {
      const a0 = (j - 1) * TUBE_SIDES;
      const b0 = j * TUBE_SIDES;
      for (let i = 0; i < TUBE_SIDES; i++) {
        const i1 = (i + 1) % TUBE_SIDES;
        indices[idx++] = a0 + i;
        indices[idx++] = b0 + i;
        indices[idx++] = a0 + i1;
        indices[idx++] = a0 + i1;
        indices[idx++] = b0 + i;
        indices[idx++] = b0 + i1;
      }
      cumIndices[owner[j]] = idx;
    }
  }
  // Mouvements sans sous-segment propre (trajets à vide) : même compte que le précédent.
  for (let k = 1; k < moves.length; k++) {
    if (cumIndices[k] < cumIndices[k - 1]) cumIndices[k] = cumIndices[k - 1];
  }

  const mesh = new BABYLON.Mesh(name, scene);
  const data = new BABYLON.VertexData();
  data.positions = positions;
  data.normals = normals;
  data.colors = colors;
  data.indices = indices.subarray(0, idx);
  data.applyToMesh(mesh);
  mesh.material = material;
  finalizePathMesh(mesh);
  return { mesh, cumIndices, indicesPerStep };
}

