import * as BABYLON from 'babylonjs';
import { parseGCode, createGCodeLayer } from '$(pwd -W)/src/components/gcodeLayer';
const lines: string[] = ['G00 Y0 X20 Z0.3 B0 E0 F1000'];
let e = 0;
for (let i = 1; i <= 400; i++) {
  e += 0.05;
  const travel = i % 97 === 0;
  lines.push('G00 Y' + (i * 3) + ' X' + (20 + i * 0.01) + ' Z' + (0.3 + i * 0.002) + ' B' + (i % 50) + (travel ? '' : ' E' + e.toFixed(3)) + ' F1000');
  if (i % 131 === 0) lines.push('G00 Y' + (i * 3) + ' X' + (20 + i * 0.01) + ' Z' + (0.3 + i * 0.002) + ' B' + (i % 50) + ' E' + (e += 0.5).toFixed(3));
}
const parsed = parseGCode(lines.join('\n'));
const engine = new BABYLON.NullEngine();
const scene = new BABYLON.Scene(engine);
const anchor = new BABYLON.TransformNode('a', scene);
const layer = createGCodeLayer(scene, anchor);
layer.load(parsed);
const mesh = scene.getMeshByName('gcodeExtruded') as BABYLON.Mesh;
const idx = mesh.getIndices()!;
const nv = mesh.getTotalVertices();
let bad = 0; for (const i of idx) if (i >= nv) bad++;
const pos = mesh.getVerticesData('position')!;
let nan = 0; for (const p of pos) if (!Number.isFinite(p)) nan++;
console.log('moves', parsed.moves.length, 'verts', nv, 'indices', idx.length, 'out-of-range', bad, 'NaN', nan);
const counts: number[] = [];
for (const t of [0, 0.5, 1, 50.3, 96.9, 200.5, parsed.moves.length - 1]) {
  layer.setTime(t);
  counts.push(mesh.subMeshes[0].indexCount);
}
console.log('indexCount over t', counts.join(','), 'full', idx.length);
EOF
