import { createGCodeLayer, parseGCode } from '$ROOT/src/components/gcodeLayer';
const engine = new BABYLON.NullEngine();
const scene = new BABYLON.Scene(engine);
const anchor = new BABYLON.TransformNode('a', scene);
const added: string[] = [];
scene.onNewMeshAddedObservable.add((m) => added.push(m.name));
const layer = createGCodeLayer(scene, anchor);
layer.load(parseGCode('G00 Y0 X30 Z5 B0 E0\nG00 Y10 X30 Z5 B20 E1'));
layer.setEnabled(true);
setTimeout(() => {
  const model = scene.getTransformNodeByName('gcodeHeadModel');
  console.log('model loaded', !!model, 'primitive nozzle left', !!scene.getMeshByName('gcodeNozzle'));
  const bad = added.filter((n) => !n.startsWith('gcode'));
  console.log('meshes added without gcode prefix:', bad.length ? bad : 'none');
  const meshes = model!.getChildMeshes(false);
  let min = new BABYLON.Vector3(1e9, 1e9, 1e9), max = min.scale(-1);
  const head = scene.getTransformNodeByName('gcodeHead')!;
  // Tête remise à l'origine sans rotation pour lire le modèle en repère tête.
  head.position.setAll(0); head.rotationQuaternion = BABYLON.Quaternion.Identity();
  for (const m of meshes) { m.computeWorldMatrix(true); }
  for (const m of meshes) { const c: BABYLON.Node[] = []; for (let n: BABYLON.Node | null = m; n; n = n.parent) c.unshift(n); c.forEach((n) => (n as BABYLON.TransformNode).computeWorldMatrix(true));
    const bb = m.getBoundingInfo().boundingBox; min = BABYLON.Vector3.Minimize(min, bb.minimumWorld); max = BABYLON.Vector3.Maximize(max, bb.maximumWorld); }
  const noz = meshes.find((m) => m.name.includes('NOZZLE origin'))!.getBoundingInfo().boundingBox;
  const f = (v: BABYLON.Vector3) => [v.x, v.y, v.z].map((x) => x.toFixed(2)).join(', ');
  console.log('head bounds mm  min', f(min), ' max', f(max));
  console.log('nozzle tip face center', ((noz.minimumWorld.x + noz.maximumWorld.x) / 2).toFixed(3), noz.minimumWorld.y.toFixed(3), ((noz.minimumWorld.z + noz.maximumWorld.z) / 2).toFixed(3));
  process.exit(0);
}, 1500);
EOF
